INSERT INTO `funds` (`id`, `name`, `mandate`, `share`, `status`, `created_at`) VALUES
('crypto', 'Crypto majors', 'Trade the liquid crypto majors (BTC, ETH, SOL and the top ten by volume on Alpaca) around the clock, which makes this the only fund that can act on the nightly run. Edges to work: trend and momentum regimes, funding-rate and open-interest extremes, exchange flows and stablecoin supply, ETF creations and redemptions, protocol catalysts (upgrades, unlocks, listings). Backtest every rule on daily and hourly bars before trading it and record the experiment. Size for 24/7 volatility: stops wide enough to survive a weekend, targets set from measured ranges. Legacy media is late and consensus; weigh raw primary sources and quote the source URL for every claim acted on.', 0.2, 'active', '2026-09-02T00:00:00.000Z');
